"""Local evidence viewer for C; images are measured renders, never illustrations."""
import json,sys,html
from pathlib import Path
p=Path(sys.argv[1]);a=json.loads((p/'result.json').read_text())
labels={'B_static':'原B静态删车','initial_road_only_change':'原静态＋初始199道路','trained_road_no_gate':'原静态＋学得199道路','gate_no_road':'C静态抑制，无道路','gate_initial_road':'C抑制＋初始199道路','C_full':'C：抑制＋学得199道路','same_gate_49_initial':'同C抑制＋初始49道路','RGB_only_previous':'旧RGB拟合版本','gate_trained_color_initial_opacity':'C抑制＋学得颜色，初始opacity','gate_initial_color_trained_opacity':'C抑制＋初始颜色，学得opacity'}
rows=''.join(f'<tr><td>{label}</td><td>{a["summary"][key]["reference_MAE"]:.5f}</td><td>{a["summary"][key]["outside_MAE"]:.5f}</td></tr>' for key,label in labels.items())
text='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>C 为什么有效：组件对照</title><style>body{margin:0;background:#edf2f7;color:#173247;font:17px/1.65 system-ui}main{max-width:1250px;margin:auto;padding:28px}h1{font-size:36px}section{background:white;border:1px solid #d5e0ea;border-radius:12px;padding:24px;margin:24px 0}.good{border-left:5px solid #218e72;padding:15px;background:#e6f5ef}.warn{border-left:5px solid #c48727;padding:15px;background:#fff4df}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}img{max-width:100%;display:block}figure{margin:0}figcaption{padding:8px}select,button{font:inherit;padding:8px}table{border-collapse:collapse;width:100%}td,th{padding:10px;text-align:left;border-bottom:1px solid #dbe4ee}code{overflow-wrap:anywhere}a{color:#1462ac}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style><main>
<h1>C 为什么有效</h1><p class="good">真实199帧道路负责补充，独立静态抑制负责让路，学习opacity让道路真正承担合成。三者配合后，两处中心道路权重达到0.912 / 0.928。</p>
<p>本轮10种固定状态干预×49帧，新增训练0步。C绑定到 <code>edit_visibility/full199/checkpoint1000_from0.pth</code>。旧RGB拟合版本单独保留。未接入FreeInpaint，也未加入额外498个资格救回点。</p><img src="architecture.svg" alt="C输入、道路、编辑静态、合成和验证组件图">
<section><h2>同一个C，逐项撤掉组件</h2><p>三帧102/129/137，固定16,921个真实跨帧参考像素；这些参考参与了训练。MAE为未clamp的浮点RGB误差，错误背景可能超出[0,1]。它们不是独立测试指标，也不是隐藏道路真值。</p><table><thead><tr><th>保留的组件</th><th>参考域MAE↓</th><th>49帧目标外变化MAE↓</th></tr></thead><tbody>'''+rows+'''</tbody></table><p>同C门控下，只替换学得颜色几乎不能替代opacity的收益。固定状态替换说明当前解依赖什么，不能当成分别重训各模块的消融收益。</p></section>
<section><h2>直接看干预</h2><label>帧 <select id="raw"><option>102</option><option>129</option><option>133</option><option>137</option></select></label> <label>左侧对照 <select id="variant"></select></label><div class="grid"><figure><img id="left"><figcaption id="leftCaption"></figcaption></figure><figure><img id="right"><figcaption>C完整编辑结果</figcaption></figure></div><p id="metrics"></p><p>raw133检查目标外最坏变化。原静态删车图也不是干净真值；此处目标外保护衡量相对原静态的变化。</p></section>
<section><h2>道路自身：位置没动，opacity和颜色变了</h2><div class="grid"><figure><img src="road_initial_102.png"><figcaption>199帧初始道路</figcaption></figure><figure><img src="road_trained_102.png"><figcaption>C学得道路；固定位置/尺度/旋转</figcaption></figure></div><p class="warn">完整C不等于完整正确三维道路。道路几何逐张量保持初始化值；可见性提升可能含opacity扩大的足迹覆盖。贡献加权高斯中心深度也不是首交路面，不能将其与参考面差值直接称为几何GT误差。</p></section>
<section><h2>为什么下一步要收紧静态抑制</h2><p>目前约122万行静态高斯被选为候选，约106万行的opacity乘子低于0.5。这不是106万个点都被证实污染。当前损失压低整条静态射线的累计alpha，会同时影响正确路面和后方静态。</p><p><strong>接下来沿C：在真实道路深度之前选择性解除遮挡 → 以留出实测几何核验道路 → 只为剩余未知外观引入生成候选。</strong>原V41-B仍独立负责默认完整重建，本轮49帧重复渲染最大差为0。对没有几何证据的缺口需显式标成假设，不能拿生成纹理当几何证据。</p><p>质量仍待人工评审。<a href="REPORT.md">详细报告与下一步设计</a> · <a href="result.json">逐帧原始指标</a> · <a href="scene_binding.json">C状态依赖</a> · <a href="../index.html">完整短程报告与49帧</a></p></section>
<script>const DATA='''+json.dumps(a,ensure_ascii=False)+''';const LABELS='''+json.dumps(labels,ensure_ascii=False)+''';
const raw=document.getElementById('raw'), variant=document.getElementById('variant');
for(const [v,l] of Object.entries(LABELS)){const o=document.createElement('option');o.value=v;o.textContent=l;variant.append(o)}variant.value='gate_initial_road';
function draw(){const r=Number(raw.value),v=variant.value;document.getElementById('left').src=`${v}_${r}.png`;document.getElementById('right').src=`C_full_${r}.png`;document.getElementById('leftCaption').textContent=LABELS[v];const row=DATA.rows.find(x=>x.raw===r&&x.variant===v);document.getElementById('metrics').textContent=`左侧目标外变化 MAE ${row.outside_MAE.toFixed(5)}；P99 ${row.outside_p99.toFixed(5)}`+(row.valid_MAE===undefined?'；本帧没有跨帧颜色参考。':`；参考域 MAE ${row.valid_MAE.toFixed(5)}`)}raw.onchange=draw;variant.onchange=draw;draw();</script></main></html>'''
(p/'index.html').write_text(text,encoding='utf-8')
parent=p.parent/'index.html';s=parent.read_text(encoding='utf-8');link='<p class="good"><a href="c_mechanism/index.html">新增：C为什么有效——10种固定状态反事实与后续路线</a></p>'
if 'c_mechanism/index.html' not in s:s=s.replace('<h1>',link+'<h1>',1)
parent.write_text(s,encoding='utf-8')
for raw in [102,129,133,137]:
    for variant in labels:assert (p/f'{variant}_{raw}.png').exists()
print(json.dumps(dict(variants=len(labels),comparison_views=4,assets_valid=True,quality_accepted=False)))
